#!/usr/bin/env python3
"""fcg_common.py — FROZEN shared parser for the forefoot Cura-copy gates. Do not edit; checked by SHA256SUMS.

Physical belt frame, as written by VertexSlice: G-code Y is the belt axis, Y = 0 is the belt, and the plantar
(bottom) edge of a closed perimeter is that loop's own minimum Y. ApexCore bead height is 0.46 mm. Filament
area comes from the file's `; filament_diameter` (1.75 mm on BASE).

Bead width is the E-derived envelope from the PM measurement (APPENDIX A / CURA_FOREFOOT_METHOD):

    w = (E / length) * A / H + H * (1 - pi/4)

A 0.5 mm X column samples that envelope only where the segment is shallow enough that 1/cos(theta) <= 4
(|dx|/length >= 0.25). Steep side-walls are left out so they cannot paper over a gap between the skins.
On BASE ApexCore orthocad this reproduces the published thin-zone gap: median about +0.410 mm.

Leader block (Kendon 2026-11-21 3:57 PM MT, t2526u): ignored. Cura reference files drop layers 0-57 and any
segment on layers 58-66 whose minimum Y is above 4.5 mm. VertexSlice files drop skirt, brim, support and
prime-tower extrusions. Moves after the end-script G91 are ignored.
"""
from __future__ import annotations

import math
import os
import re
from collections import defaultdict

WORD = re.compile(r"([GMXYZEFS])([+-]?(?:\d+\.?\d*|\.\d+)(?:[eE][+-]?\d+)?)")
STAMP = re.compile(rb"^; generated by OrcaSlicer \S+ on \d{4}-\d{2}-\d{2} at \d{2}:\d{2}:\d{2}\r?$")
HEIGHT_RE = re.compile(r"^;HEIGHT:([0-9.]+)")
DIAM_RE = re.compile(r"^;\s*filament_diameter:\s*([0-9.]+)")

# Frozen scope. orthocad_sample_top_insole.stl layers 1-165; insole_sample.stl layer 31.
FOREFOOT_LAST = {"orthocad": 165, "insole": 31}
MODEL_NAMES = {
    "orthocad": "orthocad_sample_top_insole.stl",
    "insole": "insole_sample.stl",
}

COLUMN_MM = 0.5
COS_MIN = 0.25
H_BEAD = 0.46
H_CAP = H_BEAD * (1.0 - math.pi / 4.0)
DEFAULT_DIAMETER = 1.75

THIN_LO = 2.0
THIN_HI = 3.0
THICK_LO = 3.0
THICK_HI = 6.0
THIN_OVERLAP = 0.05          # mm of skin-to-skin overlap required on every thin column
THICK_OVERLAP = 0.15         # mm of contact required between inner material and each skin
CURA_THIN_GAP = -0.45        # Cura thin-section envelope gap (negative = overlap), reported only
CURA_AIR_BELT = 46.0         # percent, PM brief, thick-section belt side
CURA_AIR_DORSAL = 39.0       # percent, PM brief, thick-section dorsal side

EDGE_P99 = 0.02
EDGE_MAX = 0.05
OUTLINE_TOL = 0.02
SEAM_ALONG = 0.05            # mm, same station along the belt edge (X)
SEAM_INWARD = 0.50           # mm, centreline Y may move inward as the bead widens; a top seam is several mm
SEAM_BOTTOM = 0.15
LC_BOTTOM = 0.55             # 0.15 mm band + the 0.40 mm belt-seam lift
BOT_TOL = 0.25
CLOSE_TOL = 0.02

FLOW_CAP = 17.1              # mm^3/s, BASE outer-wall peak
FLOW_HARD = 35.0             # mm^3/s, filament_max_volumetric_speed and the L11 cap
FLOW_MIN_LEN = 0.05          # mm; shorter moves are E-rounding noise
TIME_FRACTION = 0.02

PERIM_TYPES = {"Outer wall", "Overhang wall", "WALL-OUTER"}
SKIN_TYPES = PERIM_TYPES
LEADER_TYPES = {"Skirt", "Brim", "Support", "Support interface", "Prime tower", "Wipe tower"}
TYPE_ALIAS = {
    "WALL-OUTER": "Outer wall",
    "WALL-INNER": "Inner wall",
    "FILL": "Sparse infill",
    "SKIN": "Solid infill",
}
PROCESS_M = {104, 109, 140, 190, 106, 107, 204, 220, 221, 900}
CURA_LEADER_LAST = 57
CURA_DETACH_LAST = 66
CURA_DETACH_Y = 4.5

_CACHE = {}


def filament_area(diameter):
    return math.pi * (diameter * 0.5) ** 2


def bead_width(e_mm, length_mm, area):
    return (e_mm / length_mm) * area / H_BEAD + H_CAP


def seg_point_dist(px, py, ax, ay, bx, by):
    dx, dy = bx - ax, by - ay
    L2 = dx * dx + dy * dy
    if L2 <= 1e-18:
        return math.hypot(px - ax, py - ay), 0.0
    t = max(0.0, min(1.0, ((px - ax) * dx + (py - ay) * dy) / L2))
    return math.hypot(px - (ax + t * dx), py - (ay + t * dy)), t


def seglen(d):
    return math.hypot(d["x1"] - d["x0"], d["y1"] - d["y0"])


def detect_model(path, explicit=None):
    if explicit:
        if explicit not in FOREFOOT_LAST:
            raise SystemExit("unknown model %r (use orthocad or insole)" % explicit)
        return explicit
    name = os.path.basename(path).lower()
    if "orthocad" in name:
        return "orthocad"
    if "insole_sample" in name or "insole2" in name:
        return "insole"
    raise SystemExit("pass --model orthocad|insole (cannot tell from %s)" % path)


def _leader_skip(cura, layer, y0, y1, typ):
    if typ in LEADER_TYPES:
        return True
    if not cura:
        return False
    if layer <= CURA_LEADER_LAST:
        return True
    if CURA_LEADER_LAST < layer <= CURA_DETACH_LAST and min(y0, y1) > CURA_DETACH_Y:
        return True
    return False


def parse(fn):
    """Parse a G-code file. Cached by path, mtime and size."""
    st = os.stat(fn)
    key = (os.path.abspath(fn), st.st_mtime_ns, st.st_size)
    hit = _CACHE.get(key)
    if hit is not None:
        return hit
    ev = []
    raw_lines = []
    layer_line = {}
    x = y = z = 0.0
    e_abs = 0.0
    rel = True
    f = 0.0
    layer = -1
    typ = None
    in_end = False
    cura = False
    diameter = None
    bead_heights = []
    mcodes = []
    end_line = None
    with open(fn, "rb") as fh:
        blob = fh.read()
    cura = b"Cura_SteamEngine" in blob[:4000] or b"Generated with Cura" in blob[:4000]
    text = blob.decode("utf-8", errors="replace")
    for ln, raw in enumerate(text.splitlines(), 1):
        raw_lines.append(raw)
        s = raw.strip()
        if not s:
            continue
        if s.startswith(";"):
            dm = DIAM_RE.match(s)
            if dm and diameter is None:
                diameter = float(dm.group(1))
            hm = HEIGHT_RE.match(s)
            if hm:
                hv = float(hm.group(1))
                if 0.2 <= hv <= 0.55:
                    bead_heights.append(hv)
            if s.startswith(";LAYER:"):
                try:
                    layer = int(s.split(":", 1)[1])
                except ValueError:
                    layer += 1
                layer_line.setdefault(layer, ln - 1)
                ev.append({"kind": "layer", "layer": layer, "line": ln})
            elif s.startswith(";LAYER_CHANGE"):
                layer += 1
                layer_line.setdefault(layer, ln - 1)
                ev.append({"kind": "layer", "layer": layer, "line": ln})
            elif s.startswith(";TYPE:"):
                typ = TYPE_ALIAS.get(s[6:].strip(), s[6:].strip())
                ev.append({"kind": "type", "type": typ, "layer": layer, "line": ln})
            continue
        body = s.split(";", 1)[0].strip()
        if not body:
            continue
        w = dict(WORD.findall(body))
        if "M" in w:
            m = int(float(w["M"]))
            if m == 82:
                rel = False
            elif m == 83:
                rel = True
            if m in PROCESS_M:
                mcodes.append(body)
            ev.append({"kind": "cmd", "raw": body, "m": m, "layer": layer, "line": ln, "type": typ})
            continue
        if "G" not in w:
            continue
        g = int(float(w["G"]))
        if g == 91 and end_line is None:
            in_end = True
            end_line = ln - 1
        if g == 92:
            if "E" in w:
                e_abs = float(w["E"])
            continue
        if g not in (0, 1) or in_end:
            continue
        nx = float(w["X"]) if "X" in w else x
        ny = float(w["Y"]) if "Y" in w else y
        nz = float(w["Z"]) if "Z" in w else z
        if "F" in w:
            f = float(w["F"])
        de = 0.0
        if "E" in w:
            ev_e = float(w["E"])
            de = ev_e if rel else ev_e - e_abs
            if not rel:
                e_abs = ev_e
        moved_xy = abs(nx - x) > 1e-9 or abs(ny - y) > 1e-9
        skip = _leader_skip(cura, layer, y, ny, typ) if moved_xy else False
        d = {
            "x0": x, "y0": y, "z0": z, "x1": nx, "y1": ny, "z1": nz,
            "e": de, "f": f, "line": ln, "layer": layer, "type": typ,
            "raw": body, "zmove": abs(nz - z) > 1e-9, "leader": skip,
        }
        if moved_xy and de > 1e-9:
            d["kind"] = "ext"
        elif moved_xy or d["zmove"]:
            d["kind"] = "travel"
        elif de < -1e-9:
            d["kind"] = "retract"
        elif de > 1e-9:
            d["kind"] = "prime"
        else:
            d["kind"] = "noop"
        if not skip:
            ev.append(d)
        x, y, z = nx, ny, nz
    if diameter is None:
        diameter = DEFAULT_DIAMETER
    if end_line is None:
        end_line = len(raw_lines)
    parsed = {
        "path": os.path.abspath(fn),
        "events": ev,
        "raw": raw_lines,
        "layer_line": layer_line,
        "end_line": end_line,
        "cura": cura,
        "diameter": diameter,
        "area": filament_area(diameter),
        "bead_height": (sorted(bead_heights)[len(bead_heights) // 2] if bead_heights else None),
        "mcodes": mcodes,
        "stamp_blob": blob,
    }
    _CACHE[key] = parsed
    return parsed


def perimeter_chains(ev):
    """Closed-loop finder copied from the frozen seam-fuse parser, restricted to non-leader moves."""
    chains = []
    cur = None
    for i, d in enumerate(ev):
        k = d["kind"]
        if k == "ext" and d.get("type") in PERIM_TYPES:
            if cur is None:
                cur = {"layer": d["layer"], "segs": []}
            cur["segs"].append(i)
            continue
        if k in ("travel", "retract", "layer") or k == "ext" or (k == "type" and d.get("type") not in PERIM_TYPES):
            if cur is not None:
                chains.append(cur)
                cur = None
    if cur is not None:
        chains.append(cur)
    out = []
    for c in chains:
        segs = [ev[i] for i in c["segs"]]
        pts = [(segs[0]["x0"], segs[0]["y0"])] + [(s["x1"], s["y1"]) for s in segs]
        L = sum(seglen(s) for s in segs)
        sx, sy = pts[0]
        closed = False
        if len(segs) >= 3 and L > 0:
            acc = 0.0
            for s in segs:
                if acc >= 0.5 * L:
                    dist, _ = seg_point_dist(sx, sy, s["x0"], s["y0"], s["x1"], s["y1"])
                    if dist <= CLOSE_TOL:
                        closed = True
                        break
                acc += seglen(s)
            if not closed and math.hypot(segs[-1]["x1"] - sx, segs[-1]["y1"] - sy) <= CLOSE_TOL:
                closed = True
        miny = min(p[1] for p in pts)
        maxy = max(p[1] for p in pts)
        out.append({
            "layer": c["layer"], "seg_idx": c["segs"], "segs": segs, "pts": pts,
            "length": L, "closed": closed, "start": pts[0], "end": pts[-1],
            "miny": miny, "maxy": maxy, "line": segs[0]["line"],
        })
    return out


def bottom_edge(chain, tol=BOT_TOL):
    miny = chain["miny"]
    ivs = []
    for s in chain["segs"]:
        in0, in1 = s["y0"] <= miny + tol, s["y1"] <= miny + tol
        if in0 and in1:
            a, b = sorted((s["x0"], s["x1"]))
            ivs.append([a, b])
        else:
            if in0:
                ivs.append([s["x0"], s["x0"]])
            if in1:
                ivs.append([s["x1"], s["x1"]])
    if not ivs:
        return None
    ivs.sort()
    merged = [ivs[0]]
    for a, b in ivs[1:]:
        if a <= merged[-1][1] + 1e-6:
            merged[-1][1] = max(merged[-1][1], b)
        else:
            merged.append([a, b])
    lo = min(chain["pts"], key=lambda p: p[1])
    for a, b in merged:
        if a - 1e-6 <= lo[0] <= b + 1e-6:
            return (a, b)
    return tuple(max(merged, key=lambda iv: iv[1] - iv[0]))


def bottom_stretch(chain, tol=BOT_TOL):
    be = bottom_edge(chain, tol)
    if be is None:
        return []
    miny = chain["miny"]
    out = []
    for s in chain["segs"]:
        xa, ya, xb, yb = s["x0"], s["y0"], s["x1"], s["y1"]
        in0, in1 = ya <= miny + tol, yb <= miny + tol
        if in0 and in1 and be[0] - 1e-6 <= min(xa, xb) and max(xa, xb) <= be[1] + 1e-6:
            out.append((xa, ya, xb, yb))
        else:
            if in0 and be[0] - 1e-6 <= xa <= be[1] + 1e-6:
                out.append((xa, ya, xa, ya))
            if in1 and be[0] - 1e-6 <= xb <= be[1] + 1e-6:
                out.append((xb, yb, xb, yb))
    return out


def dist_to_bottom(chain, px, py):
    best = float("inf")
    for xa, ya, xb, yb in bottom_stretch(chain):
        d, _ = seg_point_dist(px, py, xa, ya, xb, yb)
        best = min(best, d)
    return best


def on_bottom(chain, px, py, tol):
    return dist_to_bottom(chain, px, py) <= tol


def forefoot_columns(parsed, model):
    """(layer, x_bin) -> list of (lo, hi, yc, kind) for shallow forefoot beads.

    kind is 'skin' for Outer/Overhang wall and 'inner' for every other extrusion.
    """
    last = FOREFOOT_LAST[model]
    area = parsed["area"]
    cols = defaultdict(list)
    for d in parsed["events"]:
        if d["kind"] != "ext" or d.get("leader"):
            continue
        layer = d["layer"]
        if layer < 1 or layer > last:
            continue
        x0, y0, x1, y1, e = d["x0"], d["y0"], d["x1"], d["y1"], d["e"]
        dx, dy = x1 - x0, y1 - y0
        L = math.hypot(dx, dy)
        if L < 1e-6 or e <= 1e-9:
            continue
        cos = abs(dx) / L
        if cos < COS_MIN:
            continue
        w = bead_width(e, L, area)
        yhalf = (w * 0.5) / cos
        xa, xb = (x0, x1) if x0 <= x1 else (x1, x0)
        b0 = int(math.floor(xa / COLUMN_MM))
        b1 = int(math.floor(xb / COLUMN_MM))
        kind = "skin" if d.get("type") in SKIN_TYPES else "inner"
        for b in range(b0, b1 + 1):
            lo = max(xa, b * COLUMN_MM)
            hi = min(xb, (b + 1) * COLUMN_MM)
            if hi - lo <= 1e-9:
                continue
            xc = (lo + hi) * 0.5
            t = (xc - x0) / dx if abs(dx) > 1e-12 else 0.5
            t = 0.0 if t < 0.0 else (1.0 if t > 1.0 else t)
            yc = y0 + t * dy
            cols[(layer, b)].append((yc - yhalf, yc + yhalf, yc, kind))
    return cols


def _skin_pair(beads):
    """Return (plantar_lo, plantar_hi, dorsal_lo, dorsal_hi, single) or None if no skin."""
    skins = [b for b in beads if b[3] == "skin"]
    if not skins:
        return None
    lo_yc = min(b[2] for b in skins)
    hi_yc = max(b[2] for b in skins)
    if hi_yc - lo_yc < 0.20:
        lo = min(b[0] for b in skins)
        hi = max(b[1] for b in skins)
        return (lo, hi, lo, hi, True)
    mid = (lo_yc + hi_yc) * 0.5
    plow = phigh = dlow = dhigh = None
    for lo, hi, yc, _k in skins:
        if yc <= mid:
            plow = lo if plow is None else min(plow, lo)
            phigh = hi if phigh is None else max(phigh, hi)
        if yc >= mid:
            dlow = lo if dlow is None else min(dlow, lo)
            dhigh = hi if dhigh is None else max(dhigh, hi)
    if plow is None or dlow is None:
        return None
    return (plow, phigh, dlow, dhigh, False)


def section_of(pair):
    """Outer-edge thickness and the signed gap between the two skin envelopes.

    Gap is dorsal_inner - plantar_inner. Negative means the skins overlap.
    A single bead reports gap = -(its thickness), i.e. fully overlapped.
    """
    plow, phigh, dlow, dhigh, single = pair
    if single:
        return dhigh - plow, -(dhigh - plow)
    return dhigh - plow, dlow - phigh


def thin_keys(cols):
    keys = []
    for key, beads in cols.items():
        pair = _skin_pair(beads)
        if pair is None or pair[4]:
            continue
        thickness, _gap = section_of(pair)
        if THIN_LO <= thickness < THIN_HI:
            keys.append(key)
    return keys


def thick_keys(cols):
    keys = []
    for key, beads in cols.items():
        pair = _skin_pair(beads)
        if pair is None or pair[4]:
            continue
        thickness, _gap = section_of(pair)
        if THICK_LO <= thickness <= THICK_HI:
            keys.append(key)
    return keys


def column_gap(beads):
    """Skin-to-skin signed gap for a column, or None if the two skins are not both present."""
    pair = _skin_pair(beads)
    if pair is None:
        return None
    _thickness, gap = section_of(pair)
    return gap


def stack_connected(beads, min_overlap):
    """True when every bead interval joins into one component at >= min_overlap mm."""
    ivs = sorted((b[0], b[1]) for b in beads)
    if not ivs:
        return False
    comps = [[ivs[0][0], ivs[0][1]]]
    for lo, hi in ivs[1:]:
        placed = False
        for c in comps:
            ov = min(c[1], hi) - max(c[0], lo)
            if ov >= min_overlap - 1e-12:
                c[0] = min(c[0], lo)
                c[1] = max(c[1], hi)
                placed = True
                break
        if not placed:
            comps.append([lo, hi])
    changed = True
    while changed and len(comps) > 1:
        changed = False
        nxt = []
        for c in comps:
            hit = None
            for o in nxt:
                ov = min(o[1], c[1]) - max(o[0], c[0])
                if ov >= min_overlap - 1e-12:
                    hit = o
                    break
            if hit is None:
                nxt.append(c)
            else:
                hit[0] = min(hit[0], c[0])
                hit[1] = max(hit[1], c[1])
                changed = True
        comps = nxt
    return len(comps) == 1


def nearest_overlap(beads, skin_lo, skin_hi, above):
    """Overlap (negative = gap) between a skin interval and the nearest bead on one side."""
    best = None
    mid = (skin_lo + skin_hi) * 0.5
    for lo, hi, yc, _k in beads:
        if abs(lo - skin_lo) < 1e-9 and abs(hi - skin_hi) < 1e-9:
            continue
        if above and yc <= mid:
            continue
        if not above and yc >= mid:
            continue
        ov = min(skin_hi, hi) - max(skin_lo, lo)
        if best is None or ov > best:
            best = ov
    return best


def percentile(vals, q):
    if not vals:
        return None
    s = sorted(vals)
    if len(s) == 1:
        return s[0]
    pos = q * (len(s) - 1)
    lo = int(math.floor(pos))
    hi = int(math.ceil(pos))
    if lo == hi:
        return s[lo]
    w = pos - lo
    return s[lo] * (1.0 - w) + s[hi] * w


def post_forefoot_text(parsed, model):
    """Motion text of every layer after the forefoot boundary, up to the end-script G91.

    The header stamp and the settings footer sit outside this span, so a timestamp
    cannot make two slices of the same toolpath look different.
    """
    start = FOREFOOT_LAST[model] + 1
    idx = parsed["layer_line"].get(start)
    if idx is None:
        return ""
    end = parsed["end_line"]
    return "\n".join(parsed["raw"][idx:end])


def strip_stamp(blob):
    lines = blob.split(b"\n")
    hits = [i for i, ln in enumerate(lines) if STAMP.match(ln)]
    if len(hits) > 1:
        raise SystemExit("more than one OrcaSlicer stamp line")
    kept = [ln for i, ln in enumerate(lines) if i not in hits]
    return b"\n".join(kept), len(hits)


def toolpath_seconds(fn):
    """Same cruise / trapezoid clock as the frozen seam-fuse print-budget gate."""
    x = y = None
    feed = 3000.0
    accel = 8000.0
    total = 0.0
    word = re.compile(r"([XYZEF])([+-]?(?:\d+\.?\d*|\.\d+)(?:[eE][+-]?\d+)?)")
    with open(fn, errors="replace") as fh:
        for line in fh:
            if line.startswith("M204"):
                m = re.search(r"S([0-9.]+)", line)
                if m:
                    accel = float(m.group(1))
                continue
            if line.startswith(";") or not line.startswith(("G0", "G1")):
                continue
            w = dict(word.findall(line.split(";", 1)[0]))
            if "F" in w:
                feed = float(w["F"])
            nx = float(w["X"]) if "X" in w else x
            ny = float(w["Y"]) if "Y" in w else y
            de = float(w["E"]) if "E" in w else 0.0
            dist = math.hypot((nx or 0) - (x or 0), (ny or 0) - (y or 0)) if x is not None and nx is not None else 0.0
            speed = feed / 60.0
            if de > 0 and dist > 0 and speed > 0:
                total += dist / speed
            elif dist > 0.05 and speed > 0 and accel > 0:
                ad = speed * speed / (2 * accel)
                total += (2 * (speed / accel) + (dist - 2 * ad) / speed) if dist >= 2 * ad else 2 * math.sqrt(dist / accel)
            if nx is not None:
                x, y = nx, ny
    return total


def footer_time(fn):
    m = re.search(r"^; estimated printing time \(normal mode\) = (.+)$", open(fn, errors="replace").read(), re.M)
    return m.group(1).strip() if m else None


def forefoot_filament_mm(parsed, model):
    last = FOREFOOT_LAST[model]
    total = 0.0
    for d in parsed["events"]:
        if d["kind"] == "ext" and not d.get("leader") and 1 <= d["layer"] <= last and d["e"] > 0:
            total += d["e"]
    return total


def outer_edge_segments(parsed, model):
    """Per forefoot layer, the printed outer-edge segments: centreline offset by +w/2 along the outward normal."""
    last = FOREFOOT_LAST[model]
    area = parsed["area"]
    chains = [c for c in perimeter_chains(parsed["events"]) if 1 <= c["layer"] <= last]
    by_layer = defaultdict(list)
    for ch in chains:
        area_s = 0.0
        pts = ch["pts"]
        for (x0, y0), (x1, y1) in zip(pts, pts[1:]):
            area_s += x0 * y1 - x1 * y0
        ccw = area_s >= 0.0
        for s in ch["segs"]:
            x0, y0, x1, y1 = s["x0"], s["y0"], s["x1"], s["y1"]
            dx, dy = x1 - x0, y1 - y0
            L = math.hypot(dx, dy)
            if L < 1e-9 or s["e"] <= 1e-9:
                continue
            w = bead_width(s["e"], L, area)
            half = w * 0.5
            if ccw:
                ox, oy = dy / L, -dx / L
            else:
                ox, oy = -dy / L, dx / L
            by_layer[ch["layer"]].append((
                x0 + ox * half, y0 + oy * half, x1 + ox * half, y1 + oy * half, ox, oy,
            ))
    return by_layer


class _SegGrid:
    def __init__(self, segs, cell=2.0):
        self.segs = segs
        self.cell = cell
        self.cells = defaultdict(list)
        for i, seg in enumerate(segs):
            x0, y0, x1, y1 = seg[:4]
            for key in self._keys(x0, y0, x1, y1, 0):
                self.cells[key].append(i)

    def _cell(self, x, y):
        return int(math.floor(x / self.cell)), int(math.floor(y / self.cell))

    def _keys(self, x0, y0, x1, y1, pad):
        c0, c1 = self._cell(x0, y0), self._cell(x1, y1)
        keys = []
        for ix in range(min(c0[0], c1[0]) - pad, max(c0[0], c1[0]) + 1 + pad):
            for iy in range(min(c0[1], c1[1]) - pad, max(c0[1], c1[1]) + 1 + pad):
                keys.append((ix, iy))
        return keys

    def nearest(self, x, y):
        """Return (distance, segment index, closest x, closest y)."""
        if not self.segs:
            return float("inf"), None, None, None
        cx, cy = self._cell(x, y)
        best = (float("inf"), None, None, None)
        found = False
        for pad in range(0, 6):
            for ix in range(cx - pad, cx + pad + 1):
                for iy in range(cy - pad, cy + pad + 1):
                    if pad and max(abs(ix - cx), abs(iy - cy)) != pad:
                        continue
                    for i in self.cells.get((ix, iy), ()):
                        x0, y0, x1, y1 = self.segs[i][:4]
                        d, t = seg_point_dist(x, y, x0, y0, x1, y1)
                        if d < best[0]:
                            best = (d, i, x0 + t * (x1 - x0), y0 + t * (y1 - y0))
                        found = True
            if found and best[0] <= pad * self.cell:
                return best
        return best

    def dist(self, x, y):
        return self.nearest(x, y)[0]


def _samples_on(segs, step=0.5):
    pts = []
    for seg in segs:
        x0, y0, x1, y1 = seg[:4]
        L = math.hypot(x1 - x0, y1 - y0)
        n = max(1, int(L / step))
        for i in range(n):
            t = (i + 0.5) / n
            pts.append((x0 + (x1 - x0) * t, y0 + (y1 - y0) * t))
    return pts


def edge_distances(cand_parsed, base_parsed, model):
    """Both-direction distance from each file's printed outer-edge samples to the other file's edge segments."""
    a = outer_edge_segments(cand_parsed, model)
    b = outer_edge_segments(base_parsed, model)
    dists = []
    missing = 0
    layers = set(a) | set(b)
    for layer in layers:
        sa, sb = a.get(layer, []), b.get(layer, [])
        if sa and not sb:
            missing += len(_samples_on(sa))
            continue
        if sb and not sa:
            missing += len(_samples_on(sb))
            continue
        ga, gb = _SegGrid(sa), _SegGrid(sb)
        for x, y in _samples_on(sa):
            dists.append(gb.dist(x, y))
        for x, y in _samples_on(sb):
            dists.append(ga.dist(x, y))
    return dists, missing


def extrusion_outside(cand_parsed, base_parsed, model, tol=OUTLINE_TOL):
    """Forefoot cand bead rims that sit outside the BASE printed outer edge.

    The rim is the centreline offset by half the E-derived width along the
    perpendicular, the same construction as the BASE edge. A rim point on the
    outward side of the nearest BASE edge, and more than tol past it, is outside.
    A point on the inward side is inside the outline, which is where a widened
    bead is allowed to grow. The 1/cos column envelope is not used here: it
    overstates diagonal beads and would flag the outer wall against itself.
    """
    last = FOREFOOT_LAST[model]
    base_segs = outer_edge_segments(base_parsed, model)
    grids = {layer: _SegGrid(segs) for layer, segs in base_segs.items()}
    area = cand_parsed["area"]
    outside = []
    for d in cand_parsed["events"]:
        if d["kind"] != "ext" or d.get("leader"):
            continue
        layer = d["layer"]
        if layer < 1 or layer > last:
            continue
        x0, y0, x1, y1, e = d["x0"], d["y0"], d["x1"], d["y1"], d["e"]
        dx, dy = x1 - x0, y1 - y0
        L = math.hypot(dx, dy)
        if L < 1e-6 or e <= 1e-9:
            continue
        segs = base_segs.get(layer)
        grid = grids.get(layer)
        if not segs or grid is None:
            outside.append({"layer": layer, "x": round(x1, 4), "y": round(y1, 4),
                            "line": d["line"], "type": d.get("type"), "why": "no BASE outline on this layer"})
            if len(outside) >= 12:
                return outside
            continue
        w = bead_width(e, L, area)
        half = w * 0.5
        nx, ny = dy / L, -dx / L
        n = max(1, int(math.ceil(L / 0.5)))
        for i in range(n):
            t = (i + 0.5) / n
            cx = x0 + dx * t
            cy = y0 + dy * t
            for sgn in (-1.0, 1.0):
                px = cx + sgn * nx * half
                py = cy + sgn * ny * half
                dist, idx, qx, qy = grid.nearest(px, py)
                if dist <= tol or idx is None:
                    continue
                ox, oy = segs[idx][4], segs[idx][5]
                if (px - qx) * ox + (py - qy) * oy <= 1e-6:
                    continue
                outside.append({
                    "layer": layer, "x": round(px, 4), "y": round(py, 4),
                    "dist_mm": round(dist, 4), "line": d["line"], "type": d.get("type"),
                    "why": "outward of the BASE outer edge",
                })
                if len(outside) >= 12:
                    return outside
    return outside


def layer_changes(parsed, model):
    """First Z-changing travel of each forefoot layer that has a perimeter, and its end point."""
    last = FOREFOOT_LAST[model]
    out = {}
    for d in parsed["events"]:
        if d["kind"] == "travel" and d["zmove"] and 1 <= d["layer"] <= last and d["layer"] not in out:
            out[d["layer"]] = (d["x1"], d["y1"], d["line"])
    return out


def round_report(obj):
    if isinstance(obj, float):
        if math.isinf(obj) or math.isnan(obj):
            return None
        return round(obj, 6)
    if isinstance(obj, dict):
        return {k: round_report(v) for k, v in obj.items()}
    if isinstance(obj, (list, tuple)):
        return [round_report(v) for v in obj]
    return obj
